def evaluate_state(state_view, player_id):
    start = player_id * 6
    other = (1 - player_id) * 6
    store_lead = state_view.captured[player_id] - state_view.captured[1 - player_id]
    side_lead = sum(state_view.board[start:start + 6]) - sum(state_view.board[other:other + 6])
    return max(-10.0, min(10.0, (2.0 * store_lead + 0.25 * side_lead) / 3.0))

def evaluate_state(state_view, player_id):
    start = player_id * 6
    other = (1 - player_id) * 6
    my_total = state_view.captured[player_id] + sum(state_view.board[start:start + 6])
    their_total = state_view.captured[1 - player_id] + sum(state_view.board[other:other + 6])
    return max(-10.0, min(10.0, (my_total - their_total) / 2.4))
